  "scene": {
    "composition": "Khung hình điện ảnh góc rộng. Chàng cao bồi ngồi hơi lệch về phía bên trái trung tâm — điểm tỷ lệ vàng. Mặt tiền quán rượu chiếm hai phần ba hậu cảnh bên phải. Con đường bụi bặm trải dài sang bên trái hướng về đường chân trời và mặt trời lặn. Sự bất đối xứng này — công trình vững chắc bên phải đối lập khoảng không trống trải bên trái — củng cố cảm giác cô độc sâu sắc. Một bóng hình đơn độc tại ranh giới giữa nền văn minh (quán rượu) và vùng hoang dã (sa mạc rộng lớn).",

    "the_cowboy": {
      "position": "Ngồi trên một chiếc ghế gỗ mộc mạc ở hiên trước quán rượu",
      "pose": "Tựa lưng ra sau, dồn trọng lượng vào hai chân sau của ghế. Ủng trái đặt phẳng trên sàn hiên. Mắt cá chân phải gác lên đầu gối trái — thong dong, không vội vã. Tay phải cầm lỏng một ly rượu whisky miệng thấp đặt trên đầu gối phải. Ly rượu đã cạn một nửa. Tay trái đặt trên tay vịn của ghế hoặc trên đùi. Đầu hơi cúi nhẹ xuống, nhưng ánh mắt nhìn thẳng về đường chân trời — ánh nhìn xa xăm chứa đựng cả một đời sương gió. Đôi vai rộng nhưng không gồng cứng. Ngôn ngữ cơ thể nói lên rằng: Tôi đang nghỉ ngơi, nhưng chưa từng mất đi sự cảnh giác.",
      "face": "Đây phải là một khuôn mặt CỤ THỂ, không phải một chàng cao bồi chung chung. Tuổi trung niên, khoảng 40–50. Hàm vuông với đường quai hàm sắc nét lộ qua lớp râu cạo dở. Đôi mắt sâu dưới hàng lông mày rậm — mãnh liệt, sắc sảo, hơi nheo lại trước ánh hoàng hôn chói chang. Râu lởm chởm ba ngày chưa cạo, sẫm màu với vài sợi bạc ở cằm. Da rám nắng dày sương gió — vết chân chim sâu tỏa ra từ khóe mắt, nếp nhăn trán nằm ngang, rãnh cười nơi khóe miệng đã khắc sâu vĩnh viễn. Một vết sẹo đã lành mờ mảnh màu trắng ngang gò má trái. Sống mũi hơi vẹo do một lần gãy từ lâu. Đôi môi mỏng mím lại thành một đường trung tính — không cau có, cũng không mỉm cười. Khuôn mặt này đã trải qua hàng thập kỷ sống khắc nghiệt ngoài trời và điều đó hiện rõ qua từng nếp nhăn.",
      "clothing_detail": "Mũ cao bồi vành rộng, màu nâu bụi tối tăm, cũ kỹ — các vết lõm trên chóp mũ, vành mũ hơi cong và sờn ở mép, một vệt mồ hôi ố trên dải quấn quanh mũ. Áo sơ mi cotton màu trắng ngà phai màu, xắn tay áo lên giữa cẳng tay để lộ cẳng tay rám nắng với các đường gân nổi rõ. Áo gile da sẫm màu khoác ngoài áo sơ mi, đã sờn cũ — bề mặt da nứt nẻ ở một số chỗ, đường chỉ lộ rõ ở các đường may, một vài điểm da đã bị mờ sau nhiều năm sử dụng. Quần jeans màu xanh xám tối phai màu, bạc hơn ở đầu gối và đùi do ma sát, phủ một lớp bụi. Thắt lưng da bản rộng với khóa đồng thau cổ — khóa thắt lưng đón một điểm sáng sắc nét của ánh hoàng hôn. Khẩu súng lục trong bao da đeo bên hông phải — bao da cũ màu sẫm, lộ báng súng bằng gỗ, ánh thép lóe lên. Ủng da màu nâu sẫm, trầy xước, gót mòn nhẹ, dây cựa buộc chặt quanh mắt cá chân."
    },

    "the_saloon": {
      "architecture": "Quán rượu biên giới miền Tây cổ điển. Tòa nhà gỗ hai tầng với mặt tiền giả (mặt tiền nhô cao hơn đường mái thực tế để trông bề thế hơn). Được dựng từ những tấm ván gỗ xẻ thô, một số tấm bị cong vênh theo thời gian. Một tấm biển vẽ phía trên lối vào: 'SALOON' bằng chữ vàng mờ trên nền đỏ sẫm — lớp sơn đang nứt nẻ, bong tróc ở các góc, một chữ cái mờ hơn các chữ còn lại.",
      "entrance": "Cửa lửng xoay hai cánh ở trung tâm, hơi hé mở. Qua khe hở, ánh sáng vàng ấm hắt ra ngoài — ánh sáng của đèn dầu và không khí nhộn nhịp bên trong. Bạn không thấy rõ nội thất, chỉ thấy gợi mở về sự ấm cúng và ồn ào ẩn sau cánh cửa đó.",
      "windows": "Hai ô cửa sổ hai bên lối vào. Mặt kính bám bụi mờ với ánh sáng ấm áp tỏa ra từ bên trong. Một ô kính có vết nứt chạy chéo.",
      "porch": "Hiên gỗ chạy dọc theo chiều rộng của tòa nhà. Các tấm ván sàn dầm dãi nắng mưa — xám xịt ở nơi mặt trời tẩy trắng, nâu sẫm hơn ở nơi người đi lại nhẵn nhụi. Một số tấm ván hơi cong vênh, vài đầu đinh nhô lên. Các cột gỗ đẽo thô chống đỡ mái hiên.",
      "details": "Một cọc buộc ngựa phía trước với sợi dây thừng buộc vào — sợi dây căng ra, gợi ý có con ngựa đang đứng ngay ngoài khung hình. Một máng nước bằng gỗ gần cọc buộc ngựa, mặt nước đóng rêu xanh. Một thùng gỗ cạnh cửa. Tất cả đều phủ một lớp bụi sa mạc mỏng."
    },
  "constraints": {
